{
  "root_causes": [
    {
      "service": "product-catalog",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, count(*) AS spans FROM abnormal_traces WHERE service_name = 'product-catalog' GROUP BY service_name", "claim": "product-catalog emits zero spans in the abnormal window, versus 120 server spans in the normal window."},
        {"kind": "metric", "sql": "SELECT metric, count(*) n, min(value) mn, max(value) mx, round(avg(value),1) av FROM abnormal_metrics WHERE attr_k8s_deployment_name='product-catalog' AND metric IN ('container.memory.usage','container.cpu.usage') GROUP BY metric", "claim": "product-catalog memory stays flat near 0.6 MB and CPU near 0 for the whole abnormal window, versus about 14.5 MB normally."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) c, round(avg(duration)/1e6,3) ms FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE '%ProductCatalogService/GetProduct%' GROUP BY ALL", "claim": "All 169 frontend GetProduct calls to product-catalog return Error in about 0.4 ms, with no downstream server span."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) c, round(avg(duration)/1e6,3) ms FROM abnormal_traces WHERE span_name IN ('/oteldemo.ProductCatalogService/ListProducts','grpc.oteldemo.ProductCatalogService/GetProduct') OR (service_name='checkout' AND span_name LIKE '%GetProduct%') GROUP BY ALL", "claim": "Recommendation's ListProducts and checkout's GetProduct calls to product-catalog all fail quickly with Error status."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "product-catalog",
      "to": "recommendation",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) c FROM abnormal_traces WHERE service_name='recommendation' AND attr_span_kind IN ('Client','Internal') GROUP BY ALL", "claim": "All 37 recommendation ListProducts client calls and their internal get_product_list spans error out."}
      ]
    },
    {
      "from": "product-catalog",
      "to": "checkout",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) c FROM abnormal_traces WHERE service_name='checkout' AND attr_span_kind IN ('Client','Server') GROUP BY ALL", "claim": "Checkout's GetProduct client calls and its PlaceOrder server spans all error (18 each) in the abnormal window."}
      ]
    },
    {
      "from": "product-catalog",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('GET /api/products/[productId]/index') GROUP BY ALL", "claim": "Every /api/products/[productId] request at frontend returns HTTP 500 after its failed product-catalog GetProduct call."}
      ]
    },
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='frontend' AND span_name='GET /api/recommendations' GROUP BY ALL", "claim": "All 33 /api/recommendations requests at frontend return HTTP 500 in the abnormal window."}
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='frontend' AND span_name='POST /api/checkout' GROUP BY ALL", "claim": "All 23 POST /api/checkout requests at frontend return HTTP 500 in the abnormal window."}
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) c FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Frontend-proxy ingress returns 239 HTTP 500s, matching the frontend error responses it relays to users."}
      ]
    }
  ]
}
